using System;
using System.Linq;
using NUnit.Framework;
namespace FieldOps.Tests {
 // Only the empty-magazine click and the target hit are still generated by code; weapon shots and reloads are recorded clips (see WeaponAudioTests).
 public class SoundSynthTests {
  static double Energy(float[] s,int from,int to) { double e=0;for(int i=from;i<to&&i<s.Length;i++)e+=s[i]*s[i];return e; }
  static float[][] All() { return new[]{SoundSynth.DryFire(),SoundSynth.Hit()}; }
  [Test] public void EveryClipIsAudibleBoundedAndFinite() { foreach(var clip in All()) {Assert.Greater(clip.Length,1000);Assert.IsTrue(clip.All(x=>!float.IsNaN(x)&&!float.IsInfinity(x)));float peak=clip.Max(x=>Math.Abs(x));Assert.Greater(peak,.4f);Assert.LessOrEqual(peak,1f);} }
  [Test] public void ClipLengthsMatchTheirPurpose() { Assert.That(SoundSynth.DryFire().Length/44100.0,Is.InRange(.03,.1));Assert.That(SoundSynth.Hit().Length/44100.0,Is.InRange(.06,.2)); }
  [Test] public void HitDecaysInsteadOfSustaining() { var clip=SoundSynth.Hit();int q=clip.Length/4;Assert.Less(Energy(clip,clip.Length-q,clip.Length),Energy(clip,0,q)*.05); }
  [Test] public void GenerationIsDeterministic() { Assert.AreEqual(SoundSynth.Hit(),SoundSynth.Hit());Assert.AreEqual(SoundSynth.DryFire(),SoundSynth.DryFire()); }
  [Test] public void ClipsAreDistinctFromEachOther() { var clips=All();Assert.IsFalse(clips[0].Length==clips[1].Length&&clips[0].SequenceEqual(clips[1])); }
  [Test] public void OtherSampleRatesKeepTheSameDuration() { Assert.AreEqual(SoundSynth.Hit(48000).Length/48000.0,SoundSynth.Hit(44100).Length/44100.0,.001);Assert.AreEqual(SoundSynth.DryFire(22050).Length/22050.0,SoundSynth.DryFire(44100).Length/44100.0,.001); }
  [Test] public void InvalidSampleRateIsRejected() { foreach(int bad in new[]{0,-1,7999}) {Assert.Throws<ArgumentOutOfRangeException>(()=>SoundSynth.Hit(bad),"rate "+bad);Assert.Throws<ArgumentOutOfRangeException>(()=>SoundSynth.DryFire(bad),"rate "+bad);} }
 }
}
